import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Plan — Realtime Workspace Chat","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-36-realtime-workspace-chat/plan.md","filePath":"feature/content-task-workflow/3-6-36-realtime-workspace-chat/plan.md"}'),c={name:"feature/content-task-workflow/3-6-36-realtime-workspace-chat/plan.md"};function r(l,e,s,n,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-realtime-workspace-chat" tabindex="-1">Plan — Realtime Workspace Chat <a class="header-anchor" href="#plan-—-realtime-workspace-chat" aria-label="Permalink to &quot;Plan — Realtime Workspace Chat&quot;">​</a></h1><p>Liên kết: <a href="./spec.html">spec.md</a></p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><ul><li><code>brandhub-infrastructure</code>: Mongo migration cho <code>chat_messages</code>, tài liệu feature.</li><li><code>brandhub-business-service</code>: WebSocket/STOMP, JWT CONNECT interceptor, membership access service, Mongo repository, REST history/read API và outbound membership guard.</li><li><code>brandhub-api-gateway</code>: route WebSocket <code>/ws/chat/**</code> tới Business Service.</li><li><code>brandhub-web</code>: <code>@stomp/stompjs</code>, service/store/hooks/components, route chat, sidebar, i18n vi/en.</li></ul><h2 id="_2-data-model" tabindex="-1">2. Data model <a class="header-anchor" href="#_2-data-model" aria-label="Permalink to &quot;2. Data model&quot;">​</a></h2><h3 id="chat-messages" tabindex="-1"><code>chat_messages</code> <a class="header-anchor" href="#chat-messages" aria-label="Permalink to &quot;`chat_messages`&quot;">​</a></h3><ul><li><code>_id</code>: ObjectId.</li><li><code>workspaceId</code>, <code>senderMemberId</code>, <code>senderUserId</code>: UUID string.</li><li><code>senderRole</code>, <code>senderDisplayName</code>: snapshot tại thời điểm gửi.</li><li><code>content</code>: plain text 1..4000.</li><li><code>contextType</code>: <code>GENERAL|MEDIA_PACKAGE|MEDIA_CAMPAIGN</code>.</li><li><code>contextId</code>: UUID string hoặc null.</li><li><code>clientMessageId</code>: UUID do client tạo.</li><li><code>createdAt</code>: BSON date.</li></ul><p>Indexes:</p><ul><li><code>{workspaceId: 1, createdAt: -1, _id: -1}</code>.</li><li>unique <code>{workspaceId: 1, senderUserId: 1, clientMessageId: 1}</code>.</li><li><code>{workspaceId: 1, contextType: 1, contextId: 1, createdAt: -1}</code>.</li></ul><h3 id="chat-read-states" tabindex="-1"><code>chat_read_states</code> <a class="header-anchor" href="#chat-read-states" aria-label="Permalink to &quot;`chat_read_states`&quot;">​</a></h3><ul><li><code>workspaceId</code>, <code>userId</code>, <code>lastReadMessageId</code>, <code>lastReadAt</code>.</li><li>unique <code>{workspaceId: 1, userId: 1}</code>.</li></ul><h2 id="_3-api-va-realtime-contract" tabindex="-1">3. API và realtime contract <a class="header-anchor" href="#_3-api-va-realtime-contract" aria-label="Permalink to &quot;3. API và realtime contract&quot;">​</a></h2><ul><li>REST history dùng cursor Base64 chứa <code>createdAt|id</code>, trả <code>items</code>, <code>nextCursor</code>, <code>hasMore</code>.</li><li>REST read state upsert theo <code>(workspaceId,userId)</code>.</li><li>STOMP CONNECT gửi <code>Authorization: Bearer &lt;accessToken&gt;</code>.</li><li>Inbound interceptor xác thực CONNECT; SUBSCRIBE/SEND phân tích Workspace ID từ destination và re-query active membership.</li><li>Message controller lưu Mongo trước rồi publish <code>/topic/workspaces/{id}/chat</code>.</li><li><code>/user/queue/chat-errors</code> trả error code an toàn cho client.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li>Frontend mở <code>/ws/chat</code>, xác thực ở STOMP CONNECT và subscribe topic Workspace.</li><li>Frontend tải history qua REST và merge theo message ID.</li><li>Khi gửi, UI thêm optimistic item với <code>clientMessageId</code>.</li><li>Backend xác thực member/context, kiểm tra rate limit Redis, lưu Mongo và publish canonical message.</li><li>Frontend nhận event, thay optimistic item và cập nhật read state.</li><li>Mỗi SEND/SUBSCRIBE và mỗi outbound chat message đều kiểm tra membership hiện tại; member đã remove/leave không tiếp tục gửi hoặc nhận dữ liệu.</li></ol><h2 id="_5-broker" tabindex="-1">5. Broker <a class="header-anchor" href="#_5-broker" aria-label="Permalink to &quot;5. Broker&quot;">​</a></h2><ul><li>MVP dùng Spring simple broker vì topology hiện tại chỉ có một Business Service instance.</li><li>Cấu hình giữ prefix chuẩn STOMP để có thể chuyển sang RabbitMQ broker relay khi scale nhiều instance.</li><li>MongoDB luôn là source of truth; broker không giữ lịch sử.</li></ul><h2 id="_6-ui" tabindex="-1">6. UI <a class="header-anchor" href="#_6-ui" aria-label="Permalink to &quot;6. UI&quot;">​</a></h2><ul><li>Trang orchestrator <code>pages/chat/index.tsx</code> dưới 150 dòng.</li><li>Component tách riêng: header, message list, bubble, context badge, composer, connection banner.</li><li>Store chuẩn hóa theo message ID; tự reconnect có backoff; logout/workspace switch phải deactivate client.</li><li>Thêm <code>src/i18n/locales/vi/chat.json</code>, <code>src/i18n/locales/en/chat.json</code> và đăng ký trong <code>src/i18n/index.ts</code>.</li><li>Chỉ dùng semantic theme tokens và <code>dark:</code> khi cần; không hardcode raw color.</li></ul><h2 id="_7-rui-ro-va-kiem-soat" tabindex="-1">7. Rủi ro và kiểm soát <a class="header-anchor" href="#_7-rui-ro-va-kiem-soat" aria-label="Permalink to &quot;7. Rủi ro và kiểm soát&quot;">​</a></h2><ul><li><p>Sửa <code>listMyWorkspaces</code>: trả vai trò membership active trước, chỉ fallback OWNER nếu user sở hữu Agency và không có membership; thêm regression test cho Owner kiêm Manager.</p></li><li><p>Khi handshake qua Gateway trả 404 nhưng Business nhận <code>/ws/chat</code>, kiểm tra tiến trình Gateway đã nạp cấu hình mới; restart service local rồi kiểm tra HTTP 101 qua Gateway.</p></li><li><p>Browser không gửi Bearer header ở handshake: xác thực trong STOMP CONNECT, không truyền token query string.</p></li><li><p>Subscription có thể rò dữ liệu nếu chỉ bảo vệ SEND: interceptor bắt buộc kiểm tra cả SUBSCRIBE.</p></li><li><p>Retry/reconnect gây duplicate: unique index + <code>clientMessageId</code>.</p></li><li><p>Removed member còn subscription: outbound interceptor re-query membership trước khi chuyển từng chat message.</p></li><li><p>WebSocket frame không đi qua HTTP rate limiter: giới hạn riêng bằng Redis trong message service.</p></li></ul>',21)])])}const p=a(c,[["render",r]]);export{m as __pageData,p as default};
